namespace RecipeHub.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Fresh basil, Olive oil, Salt", Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute.\n5. Bake 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle olive oil.", AverageRating = 4.5, RatingCount = 12 },
        new() { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper", Steps = "1. Cook spaghetti in salted water.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat, stir in egg mixture.\n6. Serve immediately with extra pecorino.", AverageRating = 4.8, RatingCount = 20 },
        new() { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Cream, Onion, Garlic, Ginger", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and simmer.\n5. Stir in cream and garam masala.\n6. Add chicken pieces and simmer 10 minutes.", AverageRating = 4.6, RatingCount = 15 },
        new() { Id = 4, Title = "Vegetable Pad Thai", Category = "Asian", Ingredients = "Rice noodles, Tofu, Bean sprouts, Peanuts, Lime, Tamarind paste, Fish sauce, Sugar, Eggs", Steps = "1. Soak rice noodles in warm water.\n2. Press and cube tofu, pan-fry until golden.\n3. Scramble eggs in wok.\n4. Add noodles with tamarind, fish sauce, sugar mixture.\n5. Toss with bean sprouts and tofu.\n6. Serve with crushed peanuts and lime wedge.", AverageRating = 4.3, RatingCount = 8 },
        new() { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheddar cheese, Sour cream, Taco seasoning", Steps = "1. Brown ground beef in skillet.\n2. Add taco seasoning and water, simmer.\n3. Warm taco shells in oven.\n4. Dice tomato and shred lettuce.\n5. Assemble tacos with meat and toppings.\n6. Serve with sour cream and salsa.", AverageRating = 4.1, RatingCount = 10 },
        new() { Id = 6, Title = "Miso Ramen", Category = "Asian", Ingredients = "Ramen noodles, Miso paste, Pork broth, Chashu pork, Soft-boiled egg, Green onions, Nori, Corn", Steps = "1. Simmer pork broth for depth of flavor.\n2. Whisk miso paste into hot broth.\n3. Cook ramen noodles according to package.\n4. Slice chashu pork thinly.\n5. Assemble bowl: noodles, broth, toppings.\n6. Garnish with nori, corn, and green onions.", AverageRating = 4.7, RatingCount = 18 },
        new() { Id = 7, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime juice, Cilantro, Red onion, Jalapeño, Tomato, Salt", Steps = "1. Halve and pit ripe avocados.\n2. Mash to desired consistency.\n3. Dice onion, tomato, and jalapeño finely.\n4. Fold in diced vegetables and cilantro.\n5. Add lime juice and salt to taste.\n6. Serve immediately with tortilla chips.", AverageRating = 4.4, RatingCount = 22 },
        new() { Id = 8, Title = "Butter Chicken", Category = "Indian", Ingredients = "Chicken breast, Butter, Tomato puree, Cream, Onion, Garlic, Ginger, Fenugreek leaves, Spices", Steps = "1. Marinate chicken in yogurt and spices.\n2. Grill or pan-fry chicken pieces.\n3. Melt butter, sauté onion, garlic, ginger.\n4. Add tomato puree and simmer 20 minutes.\n5. Stir in cream and fenugreek leaves.\n6. Add chicken and simmer 10 more minutes.", AverageRating = 4.9, RatingCount = 25 },
    };

    private int _nextId = 9;

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round((totalStars + stars) / recipe.RatingCount, 1);
    }

    public void AddRecipe(string title, string category, string ingredients, string steps)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

